def canPartitionKSubsets(nums, k):
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    a = sorted(nums)
    if a[-1] > target:
        return False
    n = len(a)
    full = (1 << n) - 1
    dead = set()

    def go(mask, cur):
        if mask == full:
            return True
        if mask in dead:
            return False
        for i in range(n):
            if mask >> i & 1:
                continue
            if cur + a[i] > target:
                break
            if i and a[i] == a[i - 1] and not (mask >> (i - 1) & 1):
                continue
            nxt = cur + a[i]
            if go(mask | (1 << i), 0 if nxt == target else nxt):
                return True
        dead.add(mask)
        return False

    return go(0, 0)
